/* Types */
/**  A stored account. */
export type Account = {
	id: AccountId,
	status: AccountStatus,
	closed_date: string | null,
	created_at: string,
} & AccountFields;

/**  One account's figures for the account list (UI-010). */
export type AccountBalance = {
	account: AccountId,
	/**  Postings dated today or earlier. */
	current: string,
	/**  All postings, including future-dated ones. */
	ending: string,
};

/**
 *  Editable attributes of an account (ACCT-100 … ACCT-160). Used to
 *  create and to update.
 */
export type AccountFields = {
	name: string,
	account_type: AccountType,
	group: AccountGroup,
	tax_treatment: TaxTreatment,
	description: string,
	institution: string,
	account_number: string,
	contact_phone: string,
	home_url: string,
	notes: string,
	opening_date: string | null,
	show_in_bar: boolean,
	show_in_list: boolean,
	sort_order: number,
	/**  Checking, Savings, Money Market only. */
	interest_rate: string | null,
	/**  Credit Card only. */
	credit_limit: string | null,
	/**  Required for investment types; absent otherwise. */
	investment: InvestmentSettings | null,
	/**  Required for Other Asset; absent otherwise. */
	other_asset: OtherAssetSettings | null,
};

/**  Account list groups (ACCT-240). */
export type AccountGroup = "banking" | "credit" | "investments" | "retirement" | "assets" | "liabilities";

/**  Row ID of an account. */
export type AccountId = number;

/**  Open or closed (ACCT-210). */
export type AccountStatus = "open" | "closed";

/**  Account types (ACCT-010, ACCT-020; D-100). */
export type AccountType = "checking" | "savings" | "credit_card" | "cash" | "money_market" | "brokerage" | "traditional_ira" | "roth_ira" | "hsa" | 
/**  401(k)/403(b). */
"retirement_401k" | "other_asset" | "other_liability" | 
/**  Loan or mortgage; balance tracking only in 1.0. */
"loan";

/**
 *  Fixed amounts enter as scheduled; estimated ones are confirmed on
 *  entry (REC-060).
 */
export type AmountType = "fixed" | "estimated";

/**  Kind of an Other Asset account (ACCT-140). */
export type AssetSubtype = "house" | "vehicle" | "other";

/**  What happened. */
export type AuditAction = "create" | "update" | "void" | "delete" | "merge" | "close" | "reopen" | "rollback";

/**  What kind of record an audit entry describes. */
export type AuditEntity = "account" | "category" | "payee" | "tag" | "txn" | "security" | "price" | "lot" | "schedule" | "reconciliation" | "import_batch" | "saved_report";

/**  An audit entry with its changes spelled out. */
export type AuditEntry = {
	id: number,
	at: string,
	action: AuditAction,
	/**  `ui`, `import`, `scheduler`, or `system`. */
	origin: string,
	import_batch_id: number | null,
	/**
	 *  A create lists every field (`before` empty); a delete lists every
	 *  field (`after` empty); anything else lists only differing fields.
	 */
	changes: FieldChange[],
};

/**  An occurrence auto-entry could not enter. */
export type AutoEnterFailure = {
	schedule: ScheduleId,
	nominal: string,
	reason: string,
};

/**  What auto-entry did. */
export type AutoEnterReport = {
	entered: Entered[],
	/**
	 *  Schedules stopped by an error (a closed account, say). They stay in
	 *  the due list.
	 */
	failed: AutoEnterFailure[],
};

/**  Where an investment account's cash lives (INV-300). */
export type CashMode = "internal" | "linked";

/**  A stored category. */
export type Category = {
	id: CategoryId,
	/**
	 *  Set for built-in categories, which can't be renamed, moved, or
	 *  deleted.
	 */
	system: SystemCategory | null,
	created_at: string,
} & CategoryFields;

/**  Editable attributes of a category. */
export type CategoryFields = {
	parent: CategoryId | null,
	kind: CategoryKind,
	name: string,
	/**  CAT-040 flags. */
	tax_related: boolean,
	tithable: boolean,
	giving: boolean,
	/**  CAT-030: hide instead of delete. */
	hidden: boolean,
};

/**  Row ID of a category. */
export type CategoryId = number;

/**  Category kind (CAT-010). `Equity` is system-only (opening balances). */
export type CategoryKind = "income" | "expense" | "equity";

/**  A reconciled transaction changed since the last statement (RCN-030). */
export type ChangedTxn = {
	txn_id: TxnId,
	date: string | null,
	/**  Its reconciled amount on this account at the last statement. */
	was: string,
	/**  Its reconciled amount now: zero if deleted, voided, or unreconciled. */
	now: string,
	/**  The latest change: `create`, `update`, `void`, or `delete`. */
	action: AuditAction,
};

/**  Which invariant failed. */
export type Check = 
/**  `PRAGMA integrity_check` reported a problem. */
"sqlite_integrity" | 
/**  `PRAGMA foreign_key_check` found a dangling reference. */
"foreign_keys" | 
/**  A transaction's postings do not sum to zero. */
"unbalanced" | 
/**  A transaction has no posting to an account, so no register shows it. */
"no_account_posting" | 
/**  One transaction posts to the same account twice (not a holding). */
"duplicate_account_posting" | 
/**  A voided transaction has a non-zero posting. */
"void_with_amount" | 
/**  A closed account has a posting dated after its closing date. */
"posting_after_close" | 
/**  A posting links to a reconciliation that is not finished. */
"unfinished_reconciliation" | 
/**
 *  An account's reconciled postings no longer add up to its last
 *  finished statement's ending balance.
 */
"reconciled_balance_mismatch" | 
/**  Following parents from a category leads back to it. */
"category_cycle" | 
/**  A subcategory's kind differs from its parent's. */
"category_kind_mismatch";

/**  Cleared status of an account posting (glossary; RCN-020). */
export type Cleared = "unmarked" | "cleared" | 
/**  Set only by reconciliation (Phase 5) or an import (MIG-090). */
"reconciled";

/**  What sits on the other side of a register row. */
export type Counterpart = 
/**  No other posting (a zero-amount entry). */
{ kind: "none" } | { kind: "category"; id: CategoryId } | { kind: "transfer"; id: AccountId } | 
/**  More than one other posting (REG-050 "--Split--"). */
{ kind: "split" };

/**  Projected balance at the end of a day (CAL-050). */
export type DayBalance = {
	date: string,
	balance: string,
};

/**  When a schedule stops (REC-030). */
export type End = { kind: "never" } | 
/**  Occurrences dated after `date` do not happen. */
{ kind: "on_date"; date: string } | 
/**
 *  `count` occurrences remain ("# left"); entering or skipping one
 *  uses it up.
 */
{ kind: "after_count"; count: number };

/**  Changes the user makes while entering an occurrence (REC-110). */
export type EnterEdits = {
	/**  Enter it on this date instead. */
	date: string | null,
	/**
	 *  The main account's amount, for a schedule with a single line. Split
	 *  schedules are edited in the register after entering.
	 */
	amount: string | null,
	/**
	 *  The whole transaction as the user edited it in the register (any
	 *  field, splits included). When given, `date` and `amount` are
	 *  ignored, and an estimated amount counts as confirmed. Its account
	 *  must be the schedule's.
	 */
	entry: Entry | null,
};

/**  An occurrence that became a transaction. */
export type Entered = {
	schedule: ScheduleId,
	nominal: string,
	txn: TxnId,
	date: string,
};

/**  A transaction as one account's register shows it. */
export type Entry = {
	account: AccountId,
	date: string,
	payee: PayeeId | null,
	check_num: string,
	memo: string,
	notes: string,
	/**
	 *  This account's posting: − payment or charge, + deposit (for a
	 *  liability account, − is a charge and + a payment).
	 */
	amount: string,
	cleared: Cleared,
	/**  Transaction-level tags (TAG-010), stored on this account's posting. */
	tags: TagId[],
	/**  One line for a simple transaction; several for a split. */
	lines: EntryLine[],
};

/**
 *  One line on the other side of an entry: a category or a transfer
 *  account (TXN-020).
 */
export type EntryLine = {
	target: Target,
	/**  Same sign as [`Entry::amount`]; the line's posting is minus this. */
	amount: string,
	memo: string,
	/**  The other account's cleared status (transfer lines only). */
	cleared: Cleared,
	tags: TagId[],
};

/**
 *  Remind: the user enters each occurrence. Auto: entered on the due
 *  date and flagged for review (REC-070).
 */
export type EntryMode = "remind" | "auto";

export type ErrorKind = 
/**  The request broke a domain rule; show the message. */
"invalid" | "not_found" | 
/**  The row is used elsewhere; hide or close it instead. */
"in_use" | 
/**  Repeat the call with `confirmed = true` after the user agrees. */
"confirmation_required" | 
/**  Malformed input (a bad amount or date). */
"bad_input" | 
/**  Anything else: a database or internal failure. */
"internal";

/**
 *  One field that differs between the before and after snapshots.
 *  Nested values use paths like `postings[1].amount`. `None` means the
 *  field did not exist on that side.
 */
export type FieldChange = {
	path: string,
	before: string | null,
	after: string | null,
};

/**
 *  How often a schedule repeats (REC-020). Quarterly and twice a year
 *  are `Monthly` with interval 3 and 6.
 */
export type Frequency = "once" | "daily" | "weekly" | "twice_monthly" | "monthly" | "monthly_last_day" | "monthly_nth_weekday" | "yearly";

/**  One row of the reconciliation history (RCN-060). */
export type HistoryRow = {
	reconciliation: Reconciliation,
	/**  Postings it reconciled that are still reconciled. */
	item_count: number,
	items_total: string,
};

/**  Result of an integrity check. */
export type IntegrityReport = {
	issues: Issue[],
};

/**  Settings only investment accounts have (ACCT-130, INV-300, D-50). */
export type InvestmentSettings = {
	subtype: string | null,
	cash_mode: CashMode,
	/**  Required when `cash_mode` is `Linked`. */
	linked_cash_account: AccountId | null,
	mmf_mode: MmfMode,
	default_lot_method: LotMethod,
};

/**
 *  Why a command failed, in a shape the UI can act on. `kind` picks the
 *  reaction (e.g. `confirmation_required` opens a confirm dialog);
 *  `message` is display text.
 */
export type IpcError = {
	kind: ErrorKind,
	message: string,
};

/**  One failed invariant on one record. */
export type Issue = {
	check: Check,
	/**  Table of the offending record (`txn`, `posting`, `category`, ...). */
	table: string,
	/**  Its row ID, when there is one. */
	id: number | null,
	detail: string,
};

/**  One posting the user can check off. */
export type Item = {
	txn_id: TxnId,
	date: string,
	check_num: string,
	payee_name: string,
	memo: string,
	/**
	 *  This account's posting, statement sign: on a credit card a charge
	 *  is positive and a payment negative.
	 */
	amount: string,
	checked: boolean,
};

/**
 *  Lot selection methods (LOT-100, LOT-110, D-60). The prototype
 *  engine implements `Fifo` and `Specific`; the others are stored so
 *  the schema doesn't change when they arrive.
 */
export type LotMethod = "fifo" | "specific" | "average" | 
/**  Highest cost first. */
"hifo" | 
/**
 *  Minimize tax: short-term losses, long-term losses, long-term
 *  gains (smallest first), short-term gains (smallest first).
 */
"min_tax";

/**
 *  What a merge moved from the source to the target (CAT-020, PAY-030,
 *  TAG-020). Recorded as the `after` value of the merge's audit entry.
 */
export type Merged = {
	/**  ID of the surviving category, payee, or tag. */
	into: number,
	postings: number,
	txns: number,
	schedules: number,
	schedule_lines: number,
	payee_defaults: number,
	subcategories: number,
};

/**  How money market funds are held in an investment account (INV-050, D-50). */
export type MmfMode = 
/**  A security priced at $1.00. */
"security" | 
/**  Part of the account's cash balance. */
"cash";

/**  A stored occurrence row. */
export type Occurrence = {
	id: number,
	schedule: ScheduleId,
	/**  Nominal date. */
	due_date: string,
	status: OccurrenceStatus,
	override_date: string | null,
	/**  The main account's amount, when changed for this occurrence only. */
	override_amount: string | null,
	txn: TxnId | null,
	needs_review: boolean,
};

/**
 *  What became of an occurrence (REC-110). `Pending` rows carry a
 *  one-time override.
 */
export type OccurrenceStatus = "pending" | "entered" | "skipped";

/**  One occurrence as lists and the calendar show it. */
export type OccurrenceView = {
	schedule: ScheduleId,
	/**  Nominal date: identifies the occurrence. */
	nominal: string,
	/**  When it is due: weekend rule or one-time override applied. */
	date: string,
	/**  The main account's amount, override applied. */
	amount: string,
	status: OccurrenceStatus,
	account: AccountId,
	payee: PayeeId | null,
	estimated: boolean,
	mode: EntryMode,
	/**  A one-time date or amount is set. */
	overridden: boolean,
	/**  The transaction, once entered. */
	txn: TxnId | null,
	needs_review: boolean,
	/**  Pending and dated before today. */
	overdue: boolean,
	/**  Only the schedule's next occurrence can be entered or skipped. */
	actionable: boolean,
};

/**  Do the reconciled postings still add up to the last statement? */
export type OpeningCheck = {
	/**
	 *  The last finished statement's ending balance; the reconciled total
	 *  when there is none.
	 */
	expected: string,
	/**  Σ reconciled postings now. */
	actual: string,
	/**
	 *  Reconciled transactions changed since the last statement, when
	 *  `expected` and `actual` differ. May be empty: the gap can predate
	 *  the audit log (e.g. imported data).
	 */
	changed: ChangedTxn[],
	/**  `expected == actual`. */
	matches: boolean,
};

/**  Settings only Other Asset accounts have (ACCT-140). */
export type OtherAssetSettings = {
	subtype: AssetSubtype,
	linked_liability: AccountId | null,
};

/**  A stored payee. */
export type Payee = {
	id: PayeeId,
	created_at: string,
} & PayeeFields;

/**  Editable attributes of a payee, including memorized defaults (PAY-020). */
export type PayeeFields = {
	name: string,
	default_category: CategoryId | null,
	default_tag: TagId | null,
	default_memo: string,
	default_amount: string | null,
	hidden: boolean,
};

/**  Row ID of a payee. */
export type PayeeId = number;

/**  Where a reconciliation stands. */
export type ReconStatus = "in_progress" | "finished" | "abandoned";

/**  A stored reconciliation. */
export type Reconciliation = {
	id: ReconciliationId,
	account: AccountId,
	statement_date: string,
	/**
	 *  The prior statement's ending balance when the session started
	 *  (RCN-030); the reconciled postings' total if there was none.
	 */
	opening_balance: string,
	/**  Ending balance on the statement, statement sign. */
	statement_balance: string,
	status: ReconStatus,
	started_at: string,
	finished_at: string | null,
};

/**  Row ID of a reconciliation. */
export type ReconciliationId = number;

/**
 *  A repeating pattern. Field use by frequency:
 * 
 *  | frequency | fields |
 *  |---|---|
 *  | once | `start_date` |
 *  | daily, weekly, monthly_last_day, yearly | `interval` |
 *  | twice_monthly | `day1`, `day2` (`day1 < day2`) |
 *  | monthly | `day1`, `interval` |
 *  | monthly_nth_weekday | `weekday` (1 = Monday … 7 = Sunday), `week_of_month` (1–4, or −1 = last), `interval` |
 * 
 *  Weekly repeats on `start_date`'s weekday; yearly on its month and day.
 */
export type Recurrence = {
	frequency: Frequency,
	interval: number,
	day1: number | null,
	day2: number | null,
	weekday: number | null,
	week_of_month: number | null,
	start_date: string,
	weekend_rule: WeekendRule,
};

/**  A page of register rows. */
export type RegisterPage = {
	rows: RegisterRow[],
	/**  Rows matching the filters, before `limit` and `offset`. */
	total: number,
	/**  The clock's today, for the today line (REG-070). */
	today: string,
};

/**
 *  Which register rows to show (REG-040). Every filter that is set must
 *  match.
 */
export type RegisterQuery = {
	account: AccountId,
	date_from: string | null,
	date_to: string | null,
	payee: PayeeId | null,
	/**  A category and its subcategories, on any line of the transaction. */
	category: CategoryId | null,
	tag: TagId | null,
	/**  This account's cleared status. */
	cleared: Cleared | null,
	/**
	 *  Case-insensitive text found in the payee, memo, notes, check
	 *  number, line memos, or category.
	 */
	text: string | null,
	sort: RegisterSort,
	descending: boolean,
	/**  Page size; `None` returns every matching row. */
	limit: number | null,
	offset: number,
};

/**  One row of an account register (REG-010, REG-020). */
export type RegisterRow = {
	txn_id: TxnId,
	date: string,
	check_num: string,
	payee: PayeeId | null,
	payee_name: string,
	memo: string,
	status: TxnStatus,
	/**  This account's posting. */
	amount: string,
	cleared: Cleared,
	counterpart: Counterpart,
	/**
	 *  What the Category column shows: a category path, `[Account]` for a
	 *  transfer, `--Split--` (REG-050), or empty.
	 */
	category: string,
	/**
	 *  Names of the tags on the transaction's postings, comma-separated
	 *  (TAG-010); empty when none.
	 */
	tags: string,
	/**
	 *  Running balance through this row in date order, whatever the
	 *  filter or sort (REG-020).
	 */
	balance: string,
	/**  Dated after today (REG-070). */
	future: boolean,
};

/**
 *  Register columns that can be sorted (REG-040). Ties break by date, then
 *  entry order.
 */
export type RegisterSort = "date" | "check_num" | "payee" | "amount" | "category" | "memo" | "cleared" | "balance";

/**  Register footer figures (REG-060). */
export type RegisterSummary = {
	/**  Postings dated today or earlier. */
	current: string,
	/**  Cleared and reconciled postings, any date. */
	cleared: string,
	/**  All postings, including future-dated ones (REG-070). */
	ending: string,
	/**
	 *  Credit cards with a limit: limit + current balance (the balance is
	 *  negative while money is owed).
	 */
	available_credit: string | null,
};

/**  What was generated. */
export type SampleSummary = {
	accounts: number,
	categories: number,
	payees: number,
	txns: number,
};

/**  A stored schedule. */
export type Schedule = {
	id: ScheduleId,
	fields: ScheduleFields,
	/**  Nominal date of the next occurrence; `None` once ended or deleted. */
	next_due: string | null,
	status: ScheduleStatus,
	created_at: string,
};

/**  Everything the user sets on a schedule (REC-010). */
export type ScheduleFields = {
	/**  The account whose register the transaction goes in. */
	account: AccountId,
	payee: PayeeId | null,
	memo: string,
	amount_type: AmountType,
	/**  At least one. One line is a simple transaction. */
	lines: ScheduleLine[],
	recurrence: Recurrence,
	end: End,
	/**  Days before the due date it shows in the due list. */
	remind_days: number,
	mode: EntryMode,
};

/**  Row ID of a schedule. */
export type ScheduleId = number;

/**  One line of the other side of a scheduled transaction (REC-150). */
export type ScheduleLine = {
	/**  A category, or the other account of a transfer. */
	target: Target,
	/**  Same sign as the schedule's amount, like an entry line. */
	amount: string,
	memo: string,
	tag: TagId | null,
};

/**  A row of the Scheduled Transactions list (REC-300). */
export type ScheduleRow = {
	schedule: Schedule,
	/**  "How often" text. */
	how_often: string,
	amount: string,
	/**  Next due date, weekend rule applied. */
	due_date: string | null,
	/**  "# left" for an after-count schedule. */
	left: number | null,
};

/**  Where a schedule stands. */
export type ScheduleStatus = "active" | 
/**  Ran out of occurrences (end date passed or "# left" reached 0). */
"ended" | "deleted";

/**
 *  One match: a transaction as one account's register shows it. A
 *  transfer matches once in each account it touches.
 */
export type SearchHit = {
	txn_id: TxnId,
	/**  The register that shows this row. */
	account: AccountId,
	date: string,
	payee_name: string,
	memo: string,
	status: TxnStatus,
	/**  This account's posting. */
	amount: string,
	/**  As the register's Category column shows it. */
	category: string,
};

export type SearchPage = {
	rows: SearchHit[],
	/**  All matches, before `limit`. */
	total: number,
};

/**  A search across accounts (UI-conventions: navigation bar search). */
export type SearchQuery = {
	/**
	 *  Case-insensitive text found in the payee, memo, notes, check
	 *  number, line memos, or category (a transfer's `[Account]` too);
	 *  or an amount ("184.23", "1,000"), which matches any line of the
	 *  transaction. Blank finds nothing.
	 */
	text: string,
	/**  Only this account's postings; `None` searches every account. */
	account: AccountId | null,
	/**  Most rows to return, newest first. */
	limit: number,
};

/**  An in-progress reconciliation, worked out for display (RCN-020 step 3). */
export type Session = {
	reconciliation: Reconciliation,
	/**
	 *  Items dated up to the statement date, oldest first: payments
	 *  (money out of an asset; charges on a credit card) and deposits
	 *  (money in; payments and credits on a credit card).
	 */
	payments: Item[],
	deposits: Item[],
	/**  Σ reconciled postings now. */
	opening: string,
	checked_payments: string,
	checked_payment_count: number,
	checked_deposits: string,
	checked_deposit_count: number,
	/**  `opening + checked payments + checked deposits`. */
	cleared_balance: string,
	/**  `statement balance − cleared balance`. Zero lets the user finish. */
	difference: string,
	opening_check: OpeningCheck,
};

/**  What starting a reconciliation needs (RCN-020 step 1). */
export type StartInput = {
	account: AccountId,
	statement_date: string,
	/**
	 *  Statement sign, as printed: a credit card balance owed is
	 *  positive.
	 */
	statement_balance: string,
	interest: StatementItem | null,
	service_charge: StatementItem | null,
};

/**
 *  Interest earned or a service charge from the statement, entered as a
 *  transaction when the session starts (RCN-020).
 */
export type StatementItem = {
	/**  On or before the statement date. */
	date: string,
	/**
	 *  Size of the item, greater than zero. The engine picks the sign:
	 *  interest raises an asset account and is a charge on a liability;
	 *  a service charge lowers either.
	 */
	amount: string,
	category: CategoryId,
};

/**  Built-in categories seeded by migration 0001 (CAT-060, RCN-040). */
export type SystemCategory = "dividends" | "interest" | "cg_dist_short" | "cg_dist_long" | "realized_gain" | "investment_income" | "investment_fees" | "investment_expense" | "tax_withheld" | "balance_adjustment" | "opening_balance";

/**  A stored tag. */
export type Tag = {
	id: TagId,
	created_at: string,
} & TagFields;

/**  Editable attributes of a tag. */
export type TagFields = {
	name: string,
	hidden: boolean,
};

/**  Row ID of a tag. */
export type TagId = number;

/**  What a posting is to. */
export type Target = { kind: "account"; id: AccountId } | { kind: "category"; id: CategoryId };

/**  Tax treatment (ACCT-030). */
export type TaxTreatment = "taxable" | "tax_deferred" | "tax_exempt";

/**  Row ID of a transaction. Immutable (TXN-070). */
export type TxnId = number;

/**  Normal or voided (TXN-040). */
export type TxnStatus = "normal" | "void";

/**  What to do when a due date falls on a weekend (REC-050). */
export type WeekendRule = "none" | "previous" | "next";

/* Tauri Specta runtime */
async function typedError<T, E>(result: Promise<T>): Promise<{ status: "ok"; data: T } | { status: "error"; error: E }> {
    try {
        return { status: "ok", data: await result };
    } catch (e) {
        if (e instanceof Error) throw e;
        return { status: "error", error: e as any };
    }
}

